# -*- coding: utf-8 -*-
import json, os, re
TID = 't1122'
with open(f'data/baihua-tasks/{TID}.json', encoding='utf-8') as f: task=json.load(f)
TITLE = task['title']; TRANSLATOR = task['translator']
INTRO = '本儀軌全一卷，唐代不空奉詔譯，出自《大正藏》密教部，是金剛頂瑜伽「他化自在天理趣會」普賢（金剛薩埵）修行念誦儀軌。內容依序為：歸命禮三寶及五方佛、諸菩薩，入精室門彈指辟魔；誦清淨明、發悟契、金剛持大印，捨身供養阿閦、寶生、無量壽、不空成就四如來；修四無量心，結金剛合掌、金剛縛、本尊三麼耶、開心門、蓮華三昧耶等印；召罪、摧罪、散壞業障；入妙觀察智定、觀自心如日、成本尊金剛不壞身；灌頂、被甲、召請眾聖、四攝、百字真言、內外八供養，末以解界奉送、出道場作結，為密教金剛界念誦法的集成。'
TITLES = ["归命三宝·礼五方佛","礼诸菩萨·入精室门·弹指辟魔","结拳旋绕·礼三宝·诵清净明","清净明密义·观性成金刚·三业转依","发悟契·金刚持大印","金刚持真言·舍身奉献阿閦佛","舍身真言·圆满菩提心","敬礼宝生尊·舍身供·灌顶法王位","求转法轮·舍身供无量寿","求请真言·获转法轮智·敬礼不空王","献身诚请·忏悔劝请·入本尊三昧耶","四无量心真言（一）·大慈·大悲","四无量心真言（二）·大喜·大舍","金刚合掌·胜上金刚缚·金刚拳大三摩耶印","本尊三么耶契·悦喜三摩耶","开心门·金刚缚·观恶字","封闭心殿·吽字辟除结界·住大悲示威怒","莲华三昧耶·除边转心归平等智","除边真言·二乘发悲救·获普贤心","大悲平等真言·召无始妄业","召罪真言·三密集业·缚业成杵","摧罪真言","摧罪功德·秘密印散坏业障轮","散坏业障真言·莲华三昧印·净三毒","入妙观察智定·观自在王印","佛告·定中礼佛足·心成日轮真言","自心如日·观白莲华·本尊心字","我是金刚·金刚合同一体","加持坚固·成金刚不可坏身·成本尊身","本尊三么耶印·灌顶·五如来","五佛灌顶·鬘灌顶","鬘灌顶真言·甲胄缯索","被甲真言·大誓庄严慈悲甲胄","悦众圣·拍印·观本尊妙身","五相所成·智身·召入自身","观阿字成妙高山·宝楼阁·供具充满","成所作智定·不空王召集众圣","平等性智定·閼伽灌沐众圣","色召圣者入殿·索引入·锁止","锁止真言·味悦喜·歌咏·本尊印","四摄印（一）·意生·触·爱缚","四摄印（二）·意气·意生女·适悦女","四摄印（三）·爱结女·自在主女·春","四摄印（四）·夏·秋·冬","四摄依次用·召尊入身·百字真言","百字真言（一）","百字真言（二）·内外供养","八供养·嬉戏·鬘菩萨","歌供养·舞菩萨","焚香·华菩萨","灯·涂香菩萨","虚空库供养·念诵仪则","降三世解界·解脱印·奉送","结行·出道场·随喜经行"]
JIE = ["唐特進試鴻臚卿三藏沙門大廣智不空奉詔譯。先以清淨三業、為利眾生令得三身故歸命禮三寶，並稽首禮金剛身語意遍滿生死、祕密金剛界大悲依護者，及阿閦（不動）、寶生、阿彌陀、不空成就等五方無上尊。","續禮薩埵金剛、虛空藏、觀自在、毘首羯磨等諸聖尊。說修行此法者常住本尊觀，行步踐蓮華至精室門，彈指三稱「吽」，右目置「麼」字、左目置「吒」字，右日左月流散金剛光，入門顧視則諸魔消散。","以左金剛拳當心豎頭指、右手亦然，頂上三左旋指空及下界、次右旋轉，皆誦「吽」字明，次思佛常住。置禮三寶已，方誦清淨明（二手未敷蓮，加於心額喉頂）。","此明密義為「諸法自性淨，我亦自性淨」；由是加持，自他獲無垢，便於自心中觀性成金剛，三業已轉依、成三祕密門。","次作發悟契（二拳檀慧鉤、進力側相拄、二舉如鉤勢），誦祕密言；由此真語印加持，諸佛不貪寂靜味、悉從定起赴集會、觀察行人同攝受。次結金剛持大印（檀慧禪智反相叉，右膝著地置頂上，想身遍滿塵剎海、敬禮一一如來足）。","誦金剛持真言；由此印故一切正覺皆隨順。為奉事諸如來，捨身奉獻阿閦佛——金剛合掌舒頂上、全身委地以心禮。","由此真言身印，即得圓滿菩提心。","次敬禮寶生尊，為奉灌頂承事故，金剛合掌下當心、以額著地而奉獻，誦真言；由此捨身供養，即獲灌頂法王位。","為求請轉法輪，捨身供養無量壽（阿彌陀），金剛合掌置頂上、以口著地奉其身，誦真言。","由此真言求請，即獲轉妙法輪智。次敬禮不空王，為求供養羯磨故，金剛合掌當心上、以頂著地而求請，誦真言。","由是獻身誠請，便能示現種種身。次想己身於佛海前懺悔隨時勸請，如是並依略瑜伽即入本尊三昧耶，跏坐端身入正受，四無量心盡法界，修習運用如法教。","大慈真言畢，誦時演心遍三界、普施眾生樂；大悲真言畢，誦時心遍眾生界、普門為拯濟。","大喜真言畢，隨類拯救、以此明加持一切有情咸授菩提，如是利樂已方歸法界性；大捨真言畢，念時心住平等、不見自他，唯此一性相即普賢性、大菩提心。","次二手旋舞作金剛合掌印（十度初分相交），誦真言；以此印便堅固縛名勝上金剛縛，一切契皆從此生；便以禪智入滿月、進力住其背，名金剛拳大三摩耶印。","次分為二作本尊三麼耶契；才結本誓印真言，身處日輪同本尊。次呈悅喜三摩耶、能令眾聖咸歡樂（縛印忍願戒滿月、檀慧禪智相合豎）。","次開心門——觀於二乳上，右「怛囉」左「吒」，三掣金剛縛、當心如啟扇；觀前一肘間「惡」字素光色，禪智入月掌、以進力二度捻字安心內。","以前拳印明封閉心殿門；密闔心門已，分二當心前，稱吽舉右噓、次吽舉同左、三吽相鉤結，吽發伸進力、左轉領辟除、右旋成結界。作此法時應內住大悲心、外示大威怒——四面豎利牙、八臂操利械、遍身發猛焰、作大叱喝相，密跡金剛眾受教而侍立。","次結蓮華三昧耶（本縛檀慧禪智豎），由此真言密印，修習三昧速現前。次除邊轉心、令歸平等智：前印檀慧交、真言最後字，便掣密印開。","才作此明印，二乘發悲救、凡夫入佛界、佛出度眾生，皆由是加持、獲得普賢心。","由是真言故，咸住大悲心、聖凡同受悅，是名「大凡二」（大乘凡夫二眾）。次召無始來妄見所生業——縛忍願如針、進力傍如鉤，心想召諸罪、罪狀餓鬼形。","反印向心召，誦此誠實語；由是三密門盡集自他業，稱吽進力拄為索引入掌，誦「鑁」內相叉、兩兩相鉤結；已縛諸罪業，忍願伸如幢、布怛囉吒字，觀成金剛杵，相拍如摧山。","忿句及怒形能淨諸惡趣，誦明忍願拍，或三或七遍。","由此相應法，三業所積罪、無始極重障作此摧壞已，猶如劫火焚乾草胡麻等；如來大悲故開此極祕門。次結祕密印、散壞業障輪而成佛事業（金剛按惹里、進力屈背合、禪智押其側）。","為欲顯發自性故，當以蓮華三昧印置於頭左誦明；由此法加持，三毒咸消，自心大菩提當時便成就。","次入妙觀察智定——縛印仰置跏趺上，進力相背豎頭合，禪智相拄押進力，此名觀自在王印；端身正坐、舌拄上腭、唇齒合，心住大空無分別，諸佛滿空來警悟。","佛告「汝證一道淨，未證金剛瑜伽定」，便於定中禮佛足；餘文廣依瑜伽經所說。誦是真言，前所內心「惡」字從字出無量赤光、右旋成日。","由真言加持故自心如日；由未分明復誦真言，加持如盛夏日輪光明晃耀；復於日輪中觀白蓮華，置本尊心字（素白光色），成本尊契，則是金剛智真言。","由真言加持，自心智分明已，復誦真言；此密義云「我是金剛」，則三業所成金剛也，復云「我是金剛身」。作是觀時，此金剛亙周法界，一切諸佛咸入此金剛合同一體。","復加持令堅固，由是加持極堅牢不可傾動，則自知成金剛不可壞身。為欲成就本尊身，誦是真言。","次以前本尊三麼耶印真言加持心額喉頂。次作灌頂法：以金剛界自在印置頂上，次額上、次右、後左，誦真言；次頂右寶、次後法、次左業。","密印（本縛忍願如刀、進力附）加持已，五如來冠在其頂；便分為二拳至頂後進力三相繞，下散垂繒勢，是名鬘灌頂，則為已繫離垢繒。","鬘灌頂真言畢；便以二手為拳、舒進力，於進指面想「唵」字、力度面置「砧」字（綠色白光），如抽藕絲為鉀縚索；從心三繞、背後亦然，次臍及腰兩膝，又臍腰心背咽喉頸後額前頂後皆三繞下散，如垂天衣。","作是加持，則為已被三世如來大誓莊嚴慈悲甲冑，一切天魔不能為障，則能摧敗一切魔軍、作諸佛事利樂有情。","為悅眾聖、速獲成就，以二羽三相拍，誦真言；由拍印加持，一切眾聖皆歡喜。次復前觀本尊心變為本尊妙身相，如前自觀今亦然，為顯法智體無二。","前觀五相所成就——自性之法身，今所觀者是智身；住是三麼地祕門，本縛禪智入於月，誦真言；由是加持故，尊身則明顯，便召入自身。","次於所居處復觀「阿」字門，成妙高山王、上有寶樓閣；於宮殿內復安本尊身、眷屬圍繞，種種供養具、法界所有物皆悉滿其中。作是觀念時誦真言；由真言威德，一切供具皆充滿，所欲咸從空庫生。","為奉事本尊故，當往成所作智定；如是觀念加持已，當以不空王召集眾聖——定慧二羽金剛拳、交臂抱胸屈進力、彈指發聲遍世界，諦觀佛海普雲集，誦真言；由真言密印，本尊及眾聖降臨充塞虛空。","次住平等性智定，捧持閼伽眾香水，灌沐眾聖無垢身；應以金剛合掌印加持香水、誦真言。","便以色召聖者入殿內智身，以三世印、進召如鉤誦真言；召已又用聲引入智同一（進力相拄如索）；同一密合已，復以香止住（進力度鉤結如連鎖）。","固縛已，又用味悅喜（進力面相合），誦真言；應以語言而為歌詠。次結本尊印及真言。又以二手如射，名意生。","又說四攝印：二手如射名意生；二交臂如抱（慧覆定）名觸；以慧肘極安定禪進名愛縛。","又以二腰側名意氣；又以二如前耎射名意生女；又如前觸名適悅女。","又如前愛縛名愛結女；以前意氣名自在主女；又以止觀上仰如華名春。","又以止觀下覆如香名夏；又以二加眼名秋；又以二當心轉名冬。","四攝如前依次而用；次復以四明召尊入身已，復結本尊三摩耶大契、誦摩訶衍百字真言。由是加持，無上菩提尚不難得，何況諸餘成就；設犯五無間罪，才誦消滅無餘——何以故？由本尊堅住己身故。","誦金剛薩埵百字真言（本尊三摩耶百字明），為密教懺悔滅罪、堅固本尊瑜伽的核心真言；此段錄其前半。","百字真言以「摩訶三摩耶薩埵惡」作結；次以內外供養供養密言王。","固縛禪智豎名戲嬉菩薩；才作明印，麼訶囉底（大樂）女適悅契諸聖；便伸臂向前合腕名鬘菩薩。","以印從臍至口散名歌供養菩薩；由是密印及真言，金剛歌女有一切世界微塵數妓樂女以妙音聲周十方剎而為供養，得獲如來無礙辯。便以二旋舞、金剛合掌頂上散，名舞菩薩。","由是供養獲六神通。次以縛下名焚香菩薩；由是法故得香雲遍周一切佛剎。又以上散如華名華菩薩；由是得華雲周遍一切佛剎、獲如來三十二相。","以禪智豎相逼金剛縛名燈菩薩；由是得智光普照佛界而為供養、獲如來五眼。以縛當心塗香勢名塗香菩薩；由是戒香普塗佛剎故，獲得五分法身智。","復以金剛合掌置於頂上，誦前虛空庫真言，出生一切供養雲海而為供養；復住本尊羯磨儀則、隨力念誦。次執珠合掌捧於頂上、誦本明加持當心，一一與真言文句齊度，或萬千百，晝夜四時精進修。念誦畢已，復以八供養及普供養等印供養，復結本尊及眷屬印，復示三麼耶及發願等。","復降三世、左旋解界；以縛印伸忍願如針、心上掣開頂上合掌，想聖眾還本宮觀，名解脫印，誦真言。","作是法已，復如前加持灌頂、被甲、禮四如來、發願懺悔等；身住本尊觀、無間菩提心，方出道場，隨心轉經、印塔及像、隨意經行。"]

texts=[t['original_preview'] for t in task['translations']]
full=''; ranges=[]
for t in texts:
    a=len(full); full+=t; ranges.append((a,len(full)))

def is_curse(s):
    if re.search(r'（[^）]*）', s): return True
    if '二合' in s or '三合' in s: return True
    if len(s)<=30 and not re.search(r'[，。！？；：「」]', s): return True
    return False

flag=[False]*len(full)
for m in re.finditer(r'「([^」]*)」', full):
    if is_curse(m.group(1)):
        for k in range(m.start(), m.end()): flag[k]=True

def render(a,b):
    out=[]; i=a; inc=False
    while i<b:
        c=full[i]; f=flag[i]
        if f:
            if not inc: out.append('⟪'); inc=True
            if c=='「' or c=='」':
                i+=1; continue
            if c=='（':
                j=i+1
                while j<b and full[j]!='）': j+=1
                i=j+1; continue
            out.append(c); i+=1
        else:
            if inc: out.append('⟫'); inc=False
            out.append(c); i+=1
    if inc: out.append('⟫')
    return ''.join(out)

MODS=[]
for i,(a,b) in enumerate(ranges):
    body=re.sub(r'[\r\n\t ]+','',render(a,b))
    MODS.append("【%s】%s【义解】%s" % (TITLES[i], body, JIE[i]))

assert len(MODS)==len(task['translations'])==54, len(MODS)
trans=[]
for i,mod in enumerate(MODS):
    mm=re.match(r'(【[^】]+】)',mod); sec=mm.group(1) if mm else f"【段{i+1}】"
    trans.append({"section":sec,"original_preview":task['translations'][i]['original_preview'],"modern":mod})
out={"id":TID,"title":TITLE,"translator":TRANSLATOR,"mode":"白話精譯","intro":INTRO,"sutraPath":task['sutraPath'],"translations":trans}
with open(f'data/modern-translation/{TID}.json','w',encoding='utf-8') as f:
    json.dump(out,f,ensure_ascii=False,indent=2)
print(f'Wrote {TID} {len(trans)}')
